    "ward.that-test-is-no-longer-waiting": "ആ ടെസ്റ്റ് ഇനി റിസൾട്ടിനായി കാത്തിരിക്കുന്നില്ല. ബോർഡ് റിഫ്രഷ് ചെയ്യുക.",
