    "ward.these-checks-could-not-be-run": "ഈ പരിശോധനകൾ നടത്താൻ കഴിഞ്ഞില്ല, അതിനാൽ ഈ ചാർട്ട് പൂർണ്ണമാണോ എന്ന് ഉറപ്പില്ല: {types}.",
    "ward.the-pre-authorisations-could-not-be-read": "Pre-authorisations വായിക്കാൻ കഴിഞ്ഞില്ല. ഇതിൽ റെക്കോർഡ് ഒന്നും ഇല്ല എന്ന് കരുതരുത്.",
    "ward.the-adult-maximum-has-to-be": "അഡൾട്ട് മാക്സിമം ഒരു സാധാരണ നമ്പർ ആയിരിക്കണം, അല്ലെങ്കിൽ ഒഴിച്ചിടണം.",
