    "ward.the-authorisation-list-could-not-be": "ഓതറൈസേഷൻ ലിസ്റ്റ് വായിക്കാൻ കഴിഞ്ഞില്ല.",
    "ward.the-band-could-not-be-checked": "ബാൻഡ് ചെക്ക് ചെയ്യാൻ സാധിച്ചില്ല. ചെക്ക് ചെയ്യാത്തതായി പരിഗണിക്കുക.",
