    "ward.the-bill-was-cancelled-before-the": "പേയ്മെന്റ് എത്തുന്നതിനുമുമ്പ് ബിൽ ക്യാൻസൽ ചെയ്തു",
    "ward.the-bills-could-not-be-loaded": "ബില്ലുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. കുടിശ്ശിക ഒന്നും ഇല്ല എന്ന് ഇതിനെ കരുതരുത്.",
    "ward.the-chart-stays-open-and-readable": "ചാർട്ട് തുറന്നതും വായിക്കാൻ കഴിയുന്നതുമായി തുടരുന്നു. മരണം സംഭവിച്ച ശേഷം നടന്ന കാര്യങ്ങൾ രേഖപ്പെടുത്തുന്നത് സാധാരണ നടപടിയാണ്.",
    "ward.the-checklist-could-not-be-completed": "ചെക്ക്‌ലിസ്റ്റ് പൂർത്തിയാക്കാൻ കഴിഞ്ഞില്ല.",
    "ward.the-clinical-record-is-not-switched": "ഈ ആശുപത്രിയ്ക്കായി ക്ലിനിക്കൽ റെക്കോർഡ് ഓൺ ചെയ്തിട്ടില്ല, അതിനാൽ കാണിക്കാൻ മെർജ് ഹിസ്റ്ററി ഒന്നുമില്ല.",
    "ward.the-code-search-is-unavailable-record": "കോഡ് സേർച്ച് ലഭ്യമായിട്ടില്ല. രോഗനിർണ്ണയം (diagnosis) വാക്കുകളിൽ രേഖപ്പെടുത്തുക.",
    "ward.the-coding-watchlist-could-not-be": "കോഡിംഗ് വാച്ച്‌ലിസ്റ്റ് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല.",
    "ward.the-computed-findings-could-not-be": "കമ്പ്യൂട്ട് ചെയ്ത കണ്ടെത്തലുകൾ ലഭ്യമാക്കാൻ കഴിഞ്ഞില്ല ({unavailable}). MaiK-ൽ വിവരം നൽകിയിട്ടുണ്ട്.",
    "ward.the-concentration-is-what-was-recorded": "Drips-ൽ ഇൻഫ്യൂഷൻ ചാർട്ട് ചെയ്തപ്പോൾ രേഖപ്പെടുത്തിയ സാന്ദ്രതയാണിത് (concentration). ഇത് ഒരിക്കലും ഊഹിച്ചെടുക്കുന്നതല്ല.",
