    "ward.the-consultation-could-not-be-saved": "കൺസൾട്ടേഷൻ സേവ് ചെയ്യാൻ കഴിഞ്ഞില്ല.",
    "ward.the-copy-this-patient-can-be": "ഈ രോഗിക്ക് നൽകാവുന്ന കോപ്പി",
