    "ward.the-ctcae-grade-must-be-1": "CTCAE ഗ്രേഡ് 1 മുതൽ 5 വരെ ആയിരിക്കണം.",
    "ward.the-delivery-record-could-not-be": "പ്രസവ റെക്കോർഡ് വായിക്കാൻ കഴിഞ്ഞില്ല. പ്രസവം രേഖപ്പെടുത്തുന്നതിന് മുമ്പ് പേജ് റിഫ്രഷ് ചെയ്യുക, അങ്ങനെ ഇത് രണ്ടുതവണ രേഖപ്പെടുത്തപ്പെടാതിരിക്കും.",
    "ward.the-destination-list-could-not-be": "ഡെസ്റ്റിനേഷൻ ലിസ്റ്റ് വായിക്കാൻ കഴിഞ്ഞില്ല.",
    "ward.the-discharge-summary-as-the-patient": "രോഗിയുടെ സ്വന്തം പോർട്ടൽ ആക്സസ് ഇപ്പോൾ കാണിക്കുന്ന രീതിയിലുള്ള ഡിസ്ചാർജ് സമ്മറി",
    "ward.the-discharge-summary-as-the-patient2": "ഈ ഹാൻഡ്ഓവർ രേഖപ്പെടുത്തിക്കഴിഞ്ഞാൽ, രോഗിയുടെ സ്വന്തം പോർട്ടൽ ആക്സസ് കാണിക്കുന്ന രീതിയിലുള്ള ഡിസ്ചാർജ് സമ്മറി കാണാൻ സാധിക്കും",
    "ward.the-discharge-summary-is-unavailable-on": "ഈ ബിൽഡിൽ ഡിസ്ചാർജ് സമ്മറി ലഭ്യമായിട്ടില്ല.",
    "ward.the-earlier-version-is-kept-and": "മുമ്പത്തെ വേർഷൻ നിലനിർത്തിയിട്ടുണ്ട്, അത് ഇപ്പോഴും തുറക്കാൻ കഴിയും.",
