    "ward.the-feed-updated-a-version-that": "നിലവിൽ പ്രാബല്യത്തിലില്ലാത്ത ഒരു വേർഷനാണ് ഫീഡ് അപ്‌ഡേറ്റ് ചെയ്തത്.",
    "ward.the-flowsheet-could-not-be-loaded": "ഫ്ലോഷീറ്റ് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല, അതിനാൽ ട്രെൻഡുകൾ വരയ്ക്കാൻ കഴിയില്ല. ഇത് രോഗിയുടെ സ്ഥിതി ശാന്തമാണ് (stable) എന്ന് കരുതരുത്.",
    "ward.the-flowsheet-could-not-be-loaded2": "ഫ്ലോഷീറ്റ് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. ഒന്നും ചാർട്ട് ചെയ്തിട്ടില്ല എന്ന് ഇതിനെ തെറ്റായി മനസ്സിലാക്കരുത്.",
    "ward.the-forecast-could-not-be-worked": "പ്രവചനം തയ്യാറാക്കാൻ കഴിഞ്ഞില്ല{v}.",
    "ward.the-frequency-on-these-orders-could": "ഈ ഓർഡറുകളിലെ ഫ്രീക്വൻസി വായിക്കാൻ കഴിഞ്ഞില്ല, അതിനാൽ ഡോസ് സമയങ്ങൾ കണക്കാക്കിയില്ല. ഇവ പരിശോധിക്കേണ്ടതുണ്ട്.",
    "ward.the-gateway-does-not-confirm-the": "ഗേറ്റ്‌വേ പേയ്‌മെന്റ് സ്ഥിരീകരിക്കുന്നില്ല, അതിനാൽ ബിൽ പെയ്ഡ് ആയി മാർക്ക് ചെയ്തിട്ടില്ല",
    "ward.the-gateway-reported-a-different-amount": "ഗേറ്റ്‌വേ വ്യത്യാസമുള്ള തുകയോ കറൻസിയോ ആണ് റിപ്പോർട്ട് ചെയ്തത്, അതിനാൽ ബിൽ പെയ്ഡ് ആയി മാർക്ക് ചെയ്തിട്ടില്ല",
    "ward.the-headings-come-from-this-hospital": "ഹെഡ്ഡിംഗുകൾ ഈ ഹോസ്പിറ്റലിന്റെ സ്വന്തം ടെംപ്ലേറ്റുകളിൽ നിന്നുള്ളതാണ്&#39;.",
    "ward.the-hospital-snapshot-could-not-be": "ഹോസ്പിറ്റൽ സ്നാപ്പ്ഷോട്ട് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല: {err}. ഇത് പൂജ്യമായി കണക്കാക്കരുത്.",
    "ward.the-icu-record-could-not-be": "ICU റെക്കോർഡ് ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. റെക്കോർഡിൽ {what} ഇല്ല എന്ന് ഇതിനെ കണക്കാക്കരുത്.",
    "ward.the-imaging-worklist-could-not-be": "ഇമേജിംഗ് വർക്ക്ലിസ്റ്റ് വായിക്കാൻ കഴിഞ്ഞില്ല.",
    "ward.the-international-patient-summary-another-hospit": "മറ്റൊരു ഹോസ്പിറ്റലിന് ഈ രോഗിയെക്കുറിച്ച് ലഭിക്കുന്ന ഇന്റർനാഷണൽ പേഷ്യന്റ് സമറി (International Patient Summary)",
    "ward.the-list-below-may-be-out": "താഴെയുള്ള ലിസ്റ്റ് പഴയതായിരിക്കാം.",
    "ward.the-marking-does-not-match-the": "മാർക്കിംഗ് ബുക്കിംഗുമായി പൊരുത്തപ്പെടുന്നില്ല.",
    "ward.the-measures-could-not-be-loaded": "അളവുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. റിപ്പോർട്ട് ചെയ്യാൻ ഒന്നുമില്ല എന്ന് ഇതിനെ കണക്കാക്കരുത്.",
    "ward.the-microphone-is-blocked-for-this": "ഈ സൈറ്റിനായി മൈക്രോഫോൺ ബ്ലോക്ക് ചെയ്തിരിക്കുന്നു. ബ്രൗസറിൽ ഇത് അനുവദിച്ച ശേഷം വീണ്ടും ശ്രമിക്കുക.",
    "ward.the-name-has-to-match-the": "പേര് മരുന്നിന്റെ പേരുമായി കൃത്യമായി പൊരുത്തപ്പെടണം, ഇല്ലെങ്കിൽ അംഗീകാരം പ്രിസ്ക്രിപ്ഷന് ബാധകമാകില്ല. അപേക്ഷിക്കുന്നയാൾ തന്നെ അംഗീകരിക്കുന്ന ആളാകാൻ പാടില്ല.",
    "ward.the-note-templates-could-not-be": "നോട്ട് ടെംപ്ലേറ്റുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല, അതിനാൽ ഇവിടെ കുറിപ്പ് എഴുതാൻ കഴിയില്ല. ചാർട്ട് റീഫ്രഷ് ചെയ്യുക.",
