    "ward.gst-pkg-room-capped": "ഈ അഡ്മിഷനായുള്ള റൂം താരിഫ് പാക്കേജ് നിരക്കിനേക്കാൾ കൂടുതലാണ്. GST യ്ക്കായി മുഴുവൻ പാക്കേജ് നിരക്കും റൂം ചാർജായി കണക്കാക്കിയിരിക്കുന്നു. ഇഷ്യൂ ചെയ്യുന്നതിന് മുൻപ് പാക്കേജും റൂം കാറ്റഗറിയും പരിശോധിക്കുക.",
    "ward.gst-pkg-room-fallback": "GST സെറ്റിംഗ്സിൽ തിരഞ്ഞെടുത്ത മൂല്യനിർണ്ണയം ഈ പാക്കേജിനായി ഉപയോഗിക്കാൻ കഴിഞ്ഞില്ല, അതിനാൽ പബ്ലിഷ് ചെയ്ത റൂം താരിഫ് ഉപയോഗിച്ചു.",
    "ward.gst-pkg-unrecoverable": "ഈ പാക്കേജിലെ റൂം ചാർജുകളുടെ GST തുകയായ {tax} രൂപ ഹോസ്പിറ്റൽ അടയ്ക്കേണ്ടതാണ്, കാരണം പേയറുടെ പാക്കേജ് റേറ്റ് അധികമായി GST അനുവദിക്കുന്നില്ല.",
    "ward.gst-pkg-tds": "ഈ സ്കീം വിജ്ഞാപനം ചെയ്ത GST TDS ഡിഡക്റ്ററായി അടയാളപ്പെടുത്തിയിരിക്കുന്നു: ഇത് ടാക്സ് ചുമത്തിയ റൂം ചാർജുകളിൽ GST TDS കുറച്ചേക്കാം (സെക്ഷൻ 51). ഇതിന്റെ 10 ശതമാനം ക്ലെയിം ഡിഡക്ഷൻ ഇൻകം ടാക്സ് TDS ആണ്, GST അല്ല.",
    "ward.gst-exempt-footnote": "ഒരു ക്ലിനിക്കൽ സ്ഥാപനത്തിന്റെ ഹെൽത്ത് കെയർ സർവീസുകളെ GST യിൽ നിന്ന് ഒഴിവാക്കിയിട്ടുണ്ട് (നോട്ടിഫിക്കേഷൻ 12/2017-സെൻട്രൽ ടാക്സ് (റേറ്റ്), എൻട്രി 74). അഡ്മിറ്റായ രോഗിക്ക് നൽകുന്ന മരുന്നുകൾ, ഇംപ്ലാന്റുകൾ, കൺസ്യൂമബിൾസ്, ഭക്ഷണം എന്നിവ ആ സേവനത്തിന്റെ ഭാഗമാണ്.",
    "ward.e-invoicing-no-turnover": "E-invoicing എനേബിൾ ചെയ്തിട്ടില്ല: ഒഴിവാക്കപ്പെട്ട സപ്ലൈകൾ ഉൾപ്പെടെയുള്ള ഹോസ്പിറ്റലിന്റെ ആകെ ടേൺഓവർ Admin, Price list, GST settings എന്നിവയിൽ നൽകിയിട്ടില്ല. ഈ ബില്ലിലെ ഒന്നും റിപ്പോർട്ട് ചെയ്തിട്ടില്ല.",
    "ward.e-invoice-exempt-only": "ഒഴിവാക്കപ്പെട്ട സപ്ലൈകൾ e-invoicing നായി റിപ്പോർട്ട് ചെയ്യാറില്ല. ഈ Bill of Supply ക്ക് IRN ഇല്ല.",
    "ward.e-invoice-mixed-b2b": "രജിസ്റ്റർ ചെയ്ത ഒരു പേയർക്കായി ടാക്സ് ചുമത്തിയതും ഇളവ് ലഭിച്ചതുമായ ചാർജുകൾ ഈ ബില്ലിലുണ്ട്. ഇത് ഒരു Tax Invoice ആയും (e-invoicing നായി റിപ്പോർട്ട് ചെയ്തത്) വേറെയൊരു Bill of Supply ആയും നൽകും.",
    "ward.gst-note-late": "സെക്ഷൻ 34 സമയം പരിധി കഴിഞ്ഞു: ഈ നോട്ട് GST ഇല്ലാതെ നൽകുന്നു.",
    "ward.gst-note-refunded": "ഈ നോട്ട് വഴി രോഗിക്ക് GST റീഫണ്ട് ചെയ്തു{ref}.",
    "ward.gst-note-itc": "ഇൻപുട്ട് ടാക്സ് ക്രെഡിറ്റ് റിവേഴ്സൽ ബയർ സ്ഥിരീകരിച്ചു: {ref}.",
    "ward.gst-note-financial": "ഈ നോട്ടിന് GST ഇല്ല: ഇതൊരു ഫിനാൻഷ്യൽ നോട്ട് ആണ്, e-invoicing നായി റിപ്പോർട്ട് ചെയ്തിട്ടില്ല.",
    "ward.gst-room-tariff-missing": "ഈ പാക്കേജിൽ {roomCategoryName}-ലെ റൂം ദിവസങ്ങൾ ഉൾപ്പെടുന്നു, അതിന് Price list-ൽ പ്രതിദിന റൂം താരിഫ് ഇല്ല. GST കണക്കാക്കാൻ കഴിയില്ല. ഈ ബിൽ നൽകുന്നതിന് മുമ്പ് താരിഫ് ചേർക്കുക.",
    "ward.gst-rate-missing": "ഈ ഐറ്റങ്ങൾക്ക് ടാക്സ് ബാധകമാണ്, കൂടാതെ Price list-ൽ GST നിരക്ക് നൽകിയിട്ടുമില്ല, അതിനാൽ ബിൽ തയാറാക്കിയിട്ടില്ല: {codes}. ഒരു അഡ്മിനിസ്ട്രേറ്റർ ഓരോ നിരക്കും സെറ്റ് ചെയ്യണം; ഒന്നും സ്വയം കണക്കാക്കില്ല.",
    "ward.gst-note-ask-title": "ഈ ക്രഡിറ്റ് നോട്ടിന്റെ GST",
    "ward.gst-note-ask-registered": "{payerName} അനുയോജ്യമായ ഇൻപുട്ട് ടാക്സ് ക്രെഡിറ്റ് പിൻവലിച്ചതിന് ശേഷം മാത്രമേ ഈ ക്രെഡിറ്റ് നോട്ടിലെ GST ഹോസ്പിറ്റലിന്റെ ടാക്സ് കുറയ്ക്കൂ. അവരുടെ സ്ഥിരീകരണം റെക്കോർഡ് ചെയ്യുക.",
    "ward.gst-note-ask-patient": "ഈ ക്രെഡിറ്റ് നോട്ടിലെ GST രോഗിക്ക് റീഫണ്ട് ചെയ്താൽ മാത്രമേ ഹോസ്പിറ്റലിന്റെ ടാക്സ് കുറയുകയുള്ളൂ. ഈ നോട്ടിനൊപ്പം Rs {gst} GST റീഫണ്ട് ചെയ്യുക, അല്ലെങ്കിൽ GST ഇല്ലാതെ നൽകുക.",
    "ward.gst-note-ask-choice": "ഈ നോട്ട് എങ്ങനെയാണ് നൽകുന്നത്?",
    "ward.gst-note-opt-itc": "GST യോടെ: ബയർ ഇൻപുട്ട് ടാക്സ് ക്രെഡിറ്റ് പിൻവലിച്ചിട്ടുണ്ട്",
    "ward.gst-note-opt-refund": "GST യോടെ: ഈ നോട്ടിനൊപ്പം GST രോഗിക്ക് റീഫണ്ട് ചെയ്തിട്ടുണ്ട്",
    "ward.gst-note-opt-without": "GST ഇല്ലാതെ",
    "ward.gst-note-ask-ref": "ബയറുടെ കൺഫർമേഷൻ (കത്ത് അല്ലെങ്കിൽ റെഫറൻസ്)",
    "ward.gst-note-ask-refund-ref": "റീഫണ്ട് റെഫറൻസ് (ഓപ്ഷണൽ)",
    "ward.gst-note-need-ref": "ബയറുടെ സ്ഥിരീകരണം നൽകുക, അല്ലെങ്കിൽ GST ഇല്ലാതെ നോട്ട് നൽകുക.",
    "ward.get-irn-text2": "ടാക്സ് ചുമത്തിയ ലൈനുകളുടെ Tax Invoice മാത്രമേ റിപ്പോർട്ട് ചെയ്യപ്പെടൂ; Bill of Supply ഒരിക്കലും റിപ്പോർട്ട് ചെയ്യില്ല. 24 മണിക്കൂറിനുള്ളിൽ IRN റദ്ദാക്കാം; അതിനുശേഷം, ഒരു ക്രഡിറ്റ് നോട്ട് നൽകുക.",
    "ward.doc-bill-of-supply": "ബിൽ ഓഫ് സപ്ലൈ",
