    "ward.room-method-split": "പാക്കേജ് തുകയുടെ ആനുപാതികമായ വിഭജനം",
    "ward.pcpndt-no-form-f": "Obstetric ultrasound: ഈ റിക്വസ്റ്റിന് PCPNDT Form F ഇല്ല. സ്കാനിന് മുമ്പ് സ്ത്രീയുടെ ഡിക്ലറേഷൻ റെക്കോർഡ് ചെയ്യുക (rule 10(1A)).",
    "ward.pcpndt-no-declaration": "Obstetric ultrasound: Form F-ൽ സ്ത്രീയുടെ ഡിക്ലറേഷൻ ഇതുവരെ രേഖപ്പെടുത്തിയിട്ടില്ല. ഇത് സ്കാനിന് മുമ്പാണ് എടുക്കുന്നത് (rule 10(1A)).",
