    "ward.pcpndt-formf-incomplete": "Obstetric ultrasound: Form F അപൂർണ്ണമാണ് ({list}). അപൂർണ്ണമായ Form F നിയമലംഘനമായി കണക്കാക്കപ്പെടാം (Act s.4(3)).",
    "ward.stay-payer-title": "ഓരോ stay-യും ആരാണ് അടച്ചുതീർക്കുന്നത്",
    "ward.stay-payer-unreadable": "ഓരോ stay-യും ആരാണ് അടച്ചുതീർക്കുന്നത് എന്ന് വായിക്കാൻ കഴിഞ്ഞില്ല. ഇത് self-pay-ക്ക് തുല്യമല്ല.",
    "ward.stay-payer-policy": "പോളിസി {policy}",
