    "ward.stay-payer-not-saved": "Server-ലേക്ക് ബന്ധപ്പെടാൻ കഴിഞ്ഞില്ല. Payer മാറിയിട്ടുണ്ടാവില്ല; പരിശോധിക്കാൻ reload ചെയ്യുക.",
