    "ward.parties-basis-opinion": "ചാർട്ടേഡ് അക്കൗണ്ടന്റിന്റെ അഭിപ്രായം: {ref}, {date}",
    "ward.parties-basis": "അടിസ്ഥാനം: {type}, {ref}",
    "ward.parties-basis-contract": "payer-ന്റെ കോൺട്രാക്ട് അനുസരിച്ച് നിർണ്ണയിച്ചു.",
    "ward.parties-not-determined": "ഈ payer-ന്റെ കോൺട്രാക്ടിൽ നിർണ്ണയിച്ചിട്ടില്ല. അഡ്മിനിസ്ട്രേറ്റർ Admin, Integrations, Payers എന്നിവയിൽ നിർണ്ണയം റെക്കോർഡ് ചെയ്യുന്നത് വരെ പേഷ്യന്റിനെ GST റെസിപ്പിയന്റായി കണക്കാക്കും.",
