    "ward.parties-text": "payer-ന്റെ കോൺട്രാക്ട് ആണ് GST റെസിപ്പിയന്റ് ആരാണെന്ന് തീരുമാനിക്കുന്നത്. ബില്ലിന്റെ GST ഡോക്യുമെന്റുകൾ ആ റെസിപ്പിയന്റിനെ പിന്തുടരുന്നു, payer-നെയല്ല. IRN രജിസ്റ്റർ ചെയ്തുകഴിഞ്ഞാൽ ഇത് സാധ്യമല്ല.",
    "ward.parties-recipient-incomplete": "പേയർ കരാർ പ്രകാരം കോൺട്രാക്റ്റിംഗ് പാർട്ടിയാണ് GST റെസിപ്പിയന്റ്, എന്നാൽ ഇതിന്റെ GST വിവരങ്ങൾ അപൂർണ്ണമാണ്. Admin, Integrations, Payers എന്നിവയിൽ പോയി കരാർ പൂർത്തിയാക്കുക. മാറ്റങ്ങളൊന്നും വരുത്തിയിട്ടില്ല.",
