    "site.abdm.intro1": "ഈ ഹോസ്പിറ്റൽ Health Facility Registry-ൽ രജിസ്റ്റർ ചെയ്യുകയും StewardMD ബ്രിഡ്ജിനായി Software Linkage അമർത്തുകയും ചെയ്യുന്നു; തുടർന്ന് ABDM അതിന്റെ HIP ID കാണിക്കുന്നു. ഈ കാർഡിലുള്ളതൊന്നും ഇതുവരെ ABDM-മായി ബന്ധപ്പെടുന്നില്ല.",
