    "site.admin.wards.bed.maintenance": "മെയിന്റനൻസ്",
    "site.admin.staff.roleNote.admin": "പൂർണ്ണ സാങ്കേതിക അഡ്മിനിസ്ട്രേഷൻ: സ്റ്റാഫ്, വാർഡുകൾ, ബെഡുകൾ, ഡിപ്പാർട്ട്മെന്റുകൾ, റൂമുകൾ, ബില്ലിംഗ് കോൺഫിഗറേഷൻ. ക്ലിനിക്കൽ പ്രോട്ടോക്കോൾ സൈൻ-ഓഫ് അല്ല.",
    "site.admin.staff.roleNote.doctor": "പൂർണ്ണ ക്ലിനിക്കൽ വർക്ക്ഫ്ലോ: ക്യൂ, EMR, ഓർഡറുകൾ, പ്രിസ്ക്രിപ്ഷനുകൾ, സ്വന്തം രോഗികൾ.",
    "site.admin.staff.roleNote.nurse": "ഡെസ്കിലെ ക്യൂ നിയന്ത്രിക്കുന്നു, വൈറ്റലുകൾ രേഖപ്പെടുത്തുന്നു, ബെഡ്സൈഡിൽ മരുന്നുകൾ നൽകുന്നു (eMAR). പ്രിസ്ക്രിപ്ഷൻ എഴുതാൻ അനുമതിയില്ല.",
    "site.admin.staff.roleNote.reception": "രോഗികളെ രജിസ്റ്റർ ചെയ്യുകയും ചെക്ക് ഇൻ ചെയ്യുകയും ചെയ്യുന്നു, ഒരു ഡോക്ടർക്ക് അസൈൻ ചെയ്യുന്നു. ചാർട്ട് വായിക്കാം, എഡിറ്റ് ചെയ്യാൻ കഴിയില്ല.",
    "site.admin.staff.roleNote.pharmacy": "മെഡിക്കേഷൻ ഓർഡറുകൾ വായിക്കുകയും വിതരണം ചെയ്യുകയും ചെയ്യുന്നു, ചാർട്ടുമായി ഓർഡർ വെരിഫൈ ചെയ്യുന്നു. കൺസൾട്ടേഷൻ നോട്ടുകൾ ഇല്ല.",
    "site.admin.staff.roleNote.lab": "ഓർഡർ ചെയ്ത ടെസ്റ്റുകൾ കാണുകയും റിസൾട്ടുകൾ റിലീസ് ചെയ്യുകയും ചെയ്യുന്നു. മറ്റ് ചാർട്ട് ആക്സസ് ഇല്ല.",
    "site.admin.staff.roleNote.billing": "ചാർജുകൾ, ഇൻവോയ്സുകൾ, ക്ലെയിമുകൾ എന്നിവ വായിക്കുന്നു. പേയ്മെൻ്റ് സ്വീകരിക്കാൻ കഴിയില്ല (അതിനായി കാഷ്യറെ കാണുക).",
    "site.admin.staff.roleNote.him": "റിലീസ്-ഓഫ്-ഇൻഫർമേഷൻ റിക്വസ്റ്റുകൾ തീരുമാനിക്കാനും റെക്കോർഡ് ചെയ്യാനും ചാർട്ട് വായിക്കുന്നു.",
    "site.admin.staff.roleNote.bloodBank": "ക്രോസ്മാച്ച് ചെയ്യുക, ഇഷ്യൂ ചെയ്യുക, ട്രാൻസ്ഫ്യൂഷനുകൾ നൽകുക എന്നിവ മാത്രം ചെയ്യുന്നു.",
    "site.admin.staff.roleNote.radiographer": "ഇമേജിംഗ് സ്റ്റഡി എടുക്കുന്നു. ചാർട്ട് വായിക്കാം, റിപ്പോർട്ട് ഫയൽ ചെയ്യാനോ സ്റ്റഡി പ്രോട്ടോക്കോൾ ചെയ്യാനോ കഴിയില്ല.",
    "site.admin.staff.roleNote.radiologist": "ഇമേജിംഗ് സ്റ്റഡികൾ പ്രോട്ടോക്കോൾ ചെയ്യുകയും റിപ്പോർട്ട് ചെയ്യുകയും ചെയ്യുന്നു (ലാബ് റിസൾട്ട് റിലീസിന് ഉപയോഗിക്കുന്ന അതേ അതോറിറ്റി). മറ്റ് ചാർട്ട് റൈറ്റ് ആക്സസ് ഇല്ല.",
    "site.admin.staff.roleNote.obstetrician": "PCPNDT Form F, MTP റജിസ്റ്റർ എന്നിവ സൂക്ഷിക്കുന്ന ഡോക്ടർ.",
    "site.admin.staff.roleNote.publicHealth": "പബ്ലിക് ഹെൽത്ത് നോഡൽ ഓഫീസർ: ചാർട്ട് പരിശോധിക്കുകയും നോട്ടിഫൈ ചെയ്യാവുന്ന രോഗങ്ങളുടെ റജിസ്റ്ററും പ്രതിവാര IHIP എക്സ്പോർട്ടും സൂക്ഷിക്കുകയും ചെയ്യുന്നു.",
    "site.admin.staff.roleNote.supervisor": "OPD ക്യൂ നിയന്ത്രിക്കുകയും ചാർട്ട് പരിശോധിക്കുകയും ചെയ്യുന്നു. തങ്ങളുടെ പരിധിയിലുള്ള ഡിപ്പാർട്ട്മെന്റുകളുടെ സ്റ്റോർ ഇൻഡന്റുകൾ അപ്രൂവ് ചെയ്യുന്നു.",
    "site.admin.staff.roleNote.storeKeeper": "ജനറൽ സ്റ്റോറുകൾ കൈകാര്യം ചെയ്യുന്നു: ഐറ്റങ്ങൾ, സ്റ്റോർ ലൊക്കേഷനുകൾ, അപ്രൂവ് ചെയ്ത ഇൻഡന്റുകൾ ഇഷ്യൂ ചെയ്യൽ, റിസീവിംഗ്, ഓർഡറിംഗ്. ചാർട്ട് ആക്സസ് ഇല്ല.",
    "site.admin.staff.roleNote.biomedicalEngineer": "അസറ്റ് റജിസ്റ്റർ, പ്രിവന്റീവ് മെയിന്റനൻസ്, കാലിബ്രേഷൻ, ജോബ് കാർഡുകൾ എന്നിവ സൂക്ഷിക്കുന്നു. ചാർട്ട് ആക്സസ് ഇല്ല.",
