    "site.admin.seed.treatUnapproved": "ഓരോ ഐറ്റവും UNAPPROVED ആയി കണക്കാക്കുക.",
    "site.admin.seed.intro": "WardSynQ കൂടെ നൽകിയിട്ടുള്ള ക്ലിനിക്കൽ ഉള്ളടക്കം. {signatory} നിലവിലെ ഉള്ളടക്കം സൈൻ ഓഫ് ചെയ്യുന്നത് വരെ ഓരോ ഐറ്റവും UNAPPROVED ആണ്. സൈൻ ചെയ്യുന്നത് സൈൻ-ഓഫ് റെക്കോർഡ് ചെയ്യുന്നു; ഇത് സുരക്ഷാ പരിശോധനകളെ ബാധിക്കില്ല.",
