    "site.admin.seed.notSigned": "Sign ചെയ്തിട്ടില്ല:",
    "site.admin.hospital.noteWriters.title": "ആർക്കൊക്കെ Clinical note എഴുതാം",
    "site.admin.hospital.noteWriters.intro": "ഡോക്ടർമാർക്കും Admin-മാർക്കും എപ്പോഴും Note എഴുതാവുന്നതാണ്. രോഗിയുടെ Timeline-ൽ വിവരങ്ങൾ രേഖപ്പെടുത്താൻ നിങ്ങളുടെ ആശുപത്രി അനുവദിക്കുന്ന മറ്റ് റോളുകൾ ടിക് ചെയ്യുക. ഇത് അവർക്ക് Note എഴുതാൻ മാത്രം അനുവാദം നൽകുന്നു: മരുന്നുകൾ നിർദേശിക്കാനോ (prescribe), Order ചെയ്യാനോ, മറ്റെന്തെങ്കിലും മാറ്റാനോ ഇത് അനുവദിക്കുന്നില്ല.",
    "site.admin.hospital.noteWriters.alwaysAllowed": "എപ്പോഴും അനുവദിച്ചിട്ടുള്ളവർ: {roles}.",
    "site.admin.save": "Save ചെയ്യുക",
    "site.admin.hospital.noteWriters.savedNone": "Save ചെയ്തു. Prescriber-മാർക്ക് മാത്രമേ Note എഴുതാൻ കഴിയൂ.",
    "site.admin.hospital.noteWriters.savedOne": "Save ചെയ്തു. {n} അധിക റോളിന് കൂടി Note എഴുതാം.",
    "site.admin.hospital.noteWriters.savedMany": "Save ചെയ്തു. {n} അധിക റോളുകൾക്ക് കൂടി Note എഴുതാം.",
    "site.admin.hospital.printLang.title": "രോഗിയുടെ ഭാഷയിലുള്ള Printout-കൾ",
    "site.admin.hospital.printLang.toggle": "രോഗിയുടെ Prescription, Discharge summary എന്നിവയുടെ പ്രിന്റുകളിൽ രണ്ടാമതൊരു ഭാഷ കൂടി ലഭ്യമാക്കുക",
    "site.admin.hospital.printLang.intro": "ഇംഗ്ലീഷ് പ്രിന്റ് എപ്പോഴും പൂർണ്ണവും ഔദ്യോഗികവും ആയിരിക്കും. രണ്ടാമത്തെ ഭാഷ അതിനൊപ്പം ഒരു തർജ്ജമയായി രേഖപ്പെടുത്തി പ്രിന്റ് ചെയ്യപ്പെടും. ഇത് ഹെഡ്ഡിംഗുകൾ, ലേബലുകൾ, ഫിക്സഡ് ലിസ്റ്റിൽ നിന്ന് Prescriber തിരഞ്ഞെടുത്ത നിർദ്ദേശങ്ങൾ എന്നിവയെ മാത്രം ഉൾക്കൊള്ളുന്നു. മരുന്നുകളുടെ പേരുകൾ, ഡാസേജുകൾ, ഇടവേളകൾ, രോഗനിർണ്ണയങ്ങൾ (diagnoses), റിസൾട്ടുകൾ, ടൈപ്പ് ചെയ്ത മറ്റ് വിവരങ്ങൾ എന്നിവ ഇംഗ്ലീഷിൽ മാത്രം പ്രിന്റ് ചെയ്യപ്പെടും. തർജ്ജമ തയ്യാറാകാത്തവ ഇംഗ്ലീഷിൽ തന്നെ കാണിക്കും.",
    "site.admin.hospital.printLang.savedOn": "Save ചെയ്തു. പ്രിന്റുകളിൽ രണ്ടാമതൊരു ഭാഷ ലഭ്യമാണ്.",
