    "site.admin.hospital.alert.pushIntro": "പുഷ് സന്ദേശത്തിൽ വാർഡിൻ്റെയും ബെഡിൻ്റെയും പേര് മാത്രമേ ഉണ്ടാകൂ, രോഗിയുടെ പേര് ഉണ്ടാകില്ല. ഫോൺ അൺലോക്ക് ചെയ്ത ശേഷവും, അത് അയച്ച ആളുകൾക്ക് മാത്രമേ വിശദാംശങ്ങൾ കാണാനാകൂ. എന്താണ് ചെയ്തതെന്ന് വിവരിക്കുന്ന ഒരു വാചകം മുഖേനയാണ് സ്വീകരിച്ചതായി രേഖപ്പെടുത്തുന്നത്.",
