    "site.admin.hospital.alert.ownLadderLead": "ഈ ആശുപത്രി സ്വന്തം ലാഡർ ക്രമീകരിച്ചിട്ടുണ്ട്. അംഗീകരിച്ച ഡിഫോൾട്ട് ({by}, {on}) ഓർഡർ ചെയ്ത ക്ലിനീഷ്യനും ഓൺ-ഡ്യൂട്ടി ഡോക്ടർമാരും, തുടർന്ന് സൂപ്പർവൈസർമാരും ഡ്യൂട്ടിയിലുള്ള നഴ്സുമാരും, പിന്നീട് പേരുള്ള കോൺടാക്റ്റുകളുമാണ്.",
