    "site.admin.hospital.alert.smsIntro": "ഒരു ലെവലിന്റെ സമയത്തിനുള്ളിൽ ഫോണിലൊന്നും പുഷ് കൺഫേം ചെയ്തില്ലെങ്കിൽ, സ്റ്റാഫും റോളുകളും ഭാഗത്ത് സെറ്റ് ചെയ്തിട്ടുള്ള ഓരോ ആളുടെയും അലേർട്ട് മൊബൈലിലേക്ക് ഒരു തവണ SMS ആയി അയക്കും. ഇതിനായി ആദ്യ വേരിയബിൾ വാർഡും രണ്ടാമത്തേത് ബെഡും ആയിട്ടുള്ള DLT-അംഗീകൃത 2Factor ടെംപ്ലേറ്റ് ഉപയോഗിക്കുന്നു.",
