    "site.admin.hospital.alert.wardRuleNote": "ലെവൽ 2-ൽ, താഴെയുള്ള പട്ടികയിലെ \"നഴ്‌സ്\" എന്നത് ഈ റൂളിനെ കുറിക്കുന്നു. നഴ്‌സുമാർ, റസിഡന്റുമാർ, കൺസൾട്ടന്റുമാർ എന്നിവർ വാർഡ് സ്‌ക്രീനിൽ ഡ്യൂട്ടിയിൽ ഉണ്ടോ ഇല്ലയോ എന്ന് അടയാളപ്പെടുത്തുന്നു; ഓഫ് ഡ്യൂട്ടി എന്നത് അവരുടെ ഷിഫ്റ്റ് തീരുന്നതുവരെയോ 12 മണിക്കൂർ വരെയോ നിലനിൽക്കും. ഈ കാർഡിൽ റൂൾ മാറ്റാൻ കഴിയില്ല.",
