    "site.admin.hospital.alert.noWardBody": "രോഗിയെ അഡ്മിറ്റ് ചെയ്ത ഡോക്ടർ ഓഫ് ഡ്യൂട്ടി എന്ന് അടയാളപ്പെടുത്തിയിട്ടില്ലെങ്കിൽ അലേർട്ട് ആ ഡോക്ടർക്കും, ആ ഡോക്ടറുടെ ഡിപ്പാർട്ട്‌മെന്റിൽ ഇപ്പോൾ ഡ്യൂട്ടിയിലുള്ള റസിഡന്റുമാർക്കും (ഡിപ്പാർട്ട്‌മെന്റ് അറിയാത്തപ്പോൾ ആശുപത്രിയിൽ എവിടെയും) എല്ലാ ലെവലിലും ലഭിക്കും. ഡ്യൂട്ടിയിലുള്ള നഴ്‌സിനെയോ സൂപ്പർവൈസറെയോ മറ്റ് കൺസൾട്ടന്റിനെയോ അറിയിക്കില്ല. ഓർഡർ ചെയ്യുന്ന ക്ലിനീഷ്യനെയും പേരുള്ള കോൺടാക്റ്റുകളെയും ഇപ്പോഴും പേരുപറഞ്ഞ് അറിയിക്കും. അഡ്മിറ്റിംഗ് ഡോക്ടറും ഡ്യൂട്ടിയിലുള്ള റസിഡന്റും ഇല്ലെങ്കിൽ, അലേർട്ട് ആർക്കും ലഭിച്ചില്ല എന്ന് റെക്കോർഡ് ചെയ്യും.",
