    "site.admin.security.tellGovernance": "ഇൻഫർമേഷൻ ഗവേണൻസ് ലീഡിനെ അറിയിക്കുക. Restore ചെയ്യുകയോ re-import ചെയ്യുകയോ ചെയ്യരുത്.",
    "site.admin.security.restoreNote": "ഡാറ്റാബേസ് മനപ്പൂർവ്വം restore ചെയ്തതാണെങ്കിൽ (ഉദാഹരണത്തിന് point in time restore), ഈ റിപ്പോർട്ട് സ്വാഭാവികമാണ്, ഇത് അക്നോളജ് ചെയ്യുന്നത് വരെ നിലനിൽക്കും. ഈ ആശുപത്രിയുടെ ഉടമയ്ക്ക് മാത്രമേ വ്യക്തമായ കാരണവും incident reference-ഉം നൽകി ഇത് അക്നോളജ് ചെയ്യാൻ സാധിക്കൂ. വിശദീകരിക്കാൻ കഴിയാത്ത വ്യത്യാസങ്ങൾ അക്നോളജ് ചെയ്യരുത്: ആദ്യം ഇൻഫർമേഷൻ ഗവേണൻസ് ലീഡിനോട് ചോദിക്കുക.",
    "site.admin.security.ackPrevious.rewritten": "ഡാറ്റാബേസിൽ നിന്ന് വ്യത്യാസപ്പെട്ടിരിക്കുന്നു",
    "site.admin.security.ackPrevious.truncated": "ആപ്ലിക്കേഷന് താഴെയുള്ള വരികൾ നീക്കം ചെയ്തതായി കാണിച്ചു",
    "site.admin.security.ackRestore": "റിസ്റ്റോർ ചെയ്തത് സ്ഥിരീകരിച്ചു (Acknowledged restore)",
    "site.admin.security.ackLine": "{at}-ൽ {by} ഒരു ഔദ്യോഗിക റിസ്റ്റോർ സ്ഥിരീകരിച്ചു (ഇൻസിഡന്റ് {incident}). സ്ഥിരീകരണത്തിന് മുമ്പ് പുറത്തുനിന്നുള്ള കോപ്പി {previous}",
    "site.admin.security.ackPreviousFallback": "{status} എന്ന് റിപ്പോർട്ട് ചെയ്തു",
    "site.admin.security.aBreak": "ഒരു തടസ്സം",
    "site.admin.security.atChainedRow": "ചെയിൻ ചെയ്ത റോ {n}-ൽ",
    "site.admin.security.reasonGiven": "നൽകിയ കാരണം:",
    "site.admin.security.ackArchiveNote": "ഈ സ്ഥിരീകരണത്തിന് മുമ്പുള്ള ആങ്കർ ലോഗ് ഒരു ആർക്കൈവായി സൂക്ഷിക്കപ്പെടുന്നു, അത് ഒരിക്കലും ഇല്ലാതാക്കില്ല. ഇതിനുശേഷമുള്ള പുതിയ മാറ്റങ്ങൾ വീണ്ടും റിപ്പോർട്ട് ചെയ്യും.",
    "site.admin.security.ackFormTitleOrg": "ഹോസ്പിറ്റൽ ഇവന്റ് ലോഗിന്റെ ഔദ്യോഗിക റിസ്റ്റോർ സ്ഥിരീകരിക്കുക",
    "site.admin.security.ackFormTitle": "ഔദ്യോഗിക റിസ്റ്റോർ സ്ഥിരീകരിക്കുക",
    "site.admin.security.ackFormIntro": "ഇത് നിലവിലുള്ള പുറത്തെ കോപ്പി ആർക്കൈവ് ചെയ്യുകയും ഏറ്റവും പുതിയ റോയിൽ നിന്ന് വീണ്ടും ആരംഭിക്കുകയും ചെയ്യുന്നു, കൂടാതെ സ്ഥിരീകരണം നിങ്ങളുടെ പേരിൽ ഓഡിറ്റ് ട്രയലിൽ രേഖപ്പെടുത്തുകയും ചെയ്യുന്നു. റിസ്റ്റോർ പ്ലാൻ ചെയ്തതും താഴെ പറയുന്ന ഇൻസിഡന്റ് റഫറൻസിൽ രേഖപ്പെടുത്തിയതും ആണെങ്കിൽ മാത്രം ഇത് ചെയ്യുക. കാരണത്തിൽ ഒരിക്കലും രോഗിയുടെ വിവരങ്ങൾ നൽകരുത്.",
    "site.admin.security.whyRestored": "എന്തുകൊണ്ടാണ് ഡാറ്റാബേസ് റിസ്റ്റോർ ചെയ്തത് (കുറഞ്ഞത് 20 അക്ഷരങ്ങൾ)",
    "site.admin.security.whyRestoredPlaceholder": "പ്ലാൻ ചെയ്ത പോയിന്റ് ഇൻ ടൈം റിസ്റ്റോറിന് ശേഷം...",
