    "site.admin.security.ackingOrg": "ഹോസ്പിറ്റൽ ഇവന്റ് ലോഗിന്റെ ഔദ്യോഗിക റിസ്റ്റോർ നിങ്ങൾ സ്ഥിരീകരിക്കുകയാണ്.",
