    "site.admin.security.confirmAck": "സ്ഥിരീകരണം ഉറപ്പാക്കുക",
    "site.admin.security.back": "തിരികെ",
    "site.admin.security.integrityNoResult": "പരിശോധിച്ചിട്ടില്ല: ഇന്റഗ്രിറ്റി ഫലം ഒന്നും ലഭിച്ചില്ല. ഇത് ഓഡിറ്റ് ട്രയൽ സുരക്ഷിതമാണ് എന്നതിന് തുല്യമല്ല.",
    "site.admin.security.chainedRow": "ചെയിൻ ചെയ്ത വരി",
    "site.admin.security.expected": "പ്രതീക്ഷിക്കുന്നത്",
    "site.admin.security.found": "കണ്ടെത്തിയത്",
    "site.admin.security.integrityNote": "ഓരോ ഓഡിറ്റ് വരിയും അതിനു മുമ്പുള്ള വരിയുമായി ഒരു ഹാഷ് വഴി ബന്ധിപ്പിച്ചിരിക്കുന്നു, അതിനാൽ ഡാറ്റാബേസിൽ നേരിട്ട് വരുത്തുന്ന മാറ്റങ്ങളോ നീക്കം ചെയ്യലുകളോ ഇവിടെ കാണിക്കും. ഏറ്റവും പുതിയ വരികൾ ഓരോ തവണയും പരിശോധിക്കുന്നു. മണിക്കൂറിലൊരിക്കൽ ഏറ്റവും പുതിയ വരിയുടെ നമ്പർ ഡാറ്റാബേസിന് പുറത്തുള്ള രണ്ട് സ്റ്റോറുകളിലേക്ക് (KV, Firestore) കോപ്പി ചെയ്യുകയും ഇവിടെ താരതമ്യം ചെയ്യുകയും ചെയ്യുന്നു, കൂടാതെ രണ്ട് കോപ്പികളും തമ്മിൽ താരതമ്യം ചെയ്യുന്നു. ഇത് പ്രവർത്തനക്ഷമമാക്കുന്നതിന് മുമ്പ് റെക്കോർഡ് ചെയ്ത വരികൾ ലിങ്ക് ചെയ്തിട്ടില്ലാത്തതിനാൽ പരിശോധിക്കാൻ കഴിയില്ല.",
