    "site.admin.export.status.expired": "കാ കാലാവധി കഴിഞ്ഞു, ഫയലുകൾ ഡിലീറ്റ് ചെയ്തു",
    "site.admin.export.title": "ഡാറ്റ എക്സ്പോർട്ട് (FHIR)",
    "site.admin.export.intro": "ഈ ആശുപത്രിയുടെ റെക്കോർഡുകൾ FHIR R4 NDJSON ആയി, ബാക്ക്ഗ്രൗണ്ടിൽ ഓരോ റിസോഴ്സ് ടൈപ്പിനും ഒരു ഫയൽ വീതം എക്സ്പോർട്ട് ചെയ്യുന്നു. ഒരു സമയം ഒരു എക്സ്പോർട്ട് മാത്രമേ പ്രവർത്തിക്കൂ. ഫയലുകൾ ഇവിടെ നിന്നോ FHIR Bulk Data API ($export-status) വഴിയോ ഈ ആശുപത്രിയുടെ ഓതറൈസേഷനോടെ ഡൗൺലോഡ് ചെയ്യാം; ഓരോ ഡൗൺലോഡും ഓഡിറ്റ് ട്രയലിൽ രേഖപ്പെടുത്തും, 24 മണിക്കൂറിന് ശേഷം ഫയലുകൾ ഡിലീറ്റ് ചെയ്യപ്പെടും.",
    "site.admin.export.loadFailedLead": "എക്സ്പോർട്ടുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല",
    "site.admin.export.notSameAsNone": "ഇത് ഒന്നുമില്ല എന്നതിന് തുല്യമല്ല.",
    "site.admin.export.wardOption": "{name} (ഇപ്പോൾ {n} രോഗികൾ)",
