    "site.labAn.mappingHelp": "ഇവിടെ ലിസ്റ്റ് ചെയ്യാത്ത കോഡുള്ള ഫലം ലാബിന് മാപ്പ് ചെയ്യാത്തതായി കാണിക്കുകയും ഒരിക്കലും റിലീസ് ചെയ്യുകയും ഇല്ല. ഓർഡർ ചെയ്ത പേര് വാർഡിൽ ഓർഡർ ചെയ്ത ടെസ്റ്റ് അല്ലെങ്കിൽ പാനൽ ആണ്; അനലൈസറിന്റെ ഓർഡർ ക്വറി എന്ത് റൺ ചെയ്യണമെന്ന് മനസ്സിലാക്കുന്നത് ഇങ്ങനെയാണ്.",
