    "site.labAn.intro": "ലാബിലെ നെറ്റ്‌വർക്കിലുള്ള ഒരു കമ്പ്യൂട്ടറിൽ പ്രവർത്തിക്കുന്ന StewardMD analyser connector എന്ന ചെറിയ പ്രോഗ്രാം വഴിയാണ് അനലൈസറുകൾ കണക്റ്റ് ചെയ്യുന്നത് (connect-agent/analyser). ഒരു ടെക്നോളജിസ്റ്റ് റിലീസ് ചെയ്യുന്നതിനായി അവയുടെ ഫലങ്ങൾ Laboratory ബോർഡിൽ എത്തുന്നു; ഒന്നും സ്വയമേവ റിലീസ് ചെയ്യപ്പെടില്ല.",
