    "site.legal.intro": "WardSynQ നടപ്പിലാക്കുന്ന ഓരോ ആവശ്യകതയും, അതിന്റെ ഉറവിടം, സ്റ്റാറ്റസ്, തീയതികൾ എന്നിവ സഹിതം. കോടതി സ്റ്റേ ചെയ്തിട്ടില്ലെങ്കിൽ, ചോദ്യം ചെയ്യപ്പെടുന്ന ഒരു ആവശ്യകതയും നിലനിൽക്കും. State/UT വിവരങ്ങൾ അവയുടെ ഉറവിടത്തിനനുസരിച്ച് മാത്രമേ മാറുകയുള്ളൂ; നിങ്ങളുടെ State/UT ക്കായി സെറ്റ് ചെയ്യാത്ത വിവരങ്ങൾ ഈ ആശുപത്രി കോൺഫിഗർ ചെയ്യേണ്ടതാണ്.",
