    "site.gov.hmis.intro": "പ്രൈവറ്റ് സെക്കൻഡറി കെയർ ഫെസിലിറ്റിക്കായുള്ള ഗവൺമെന്റ് ഓഫ് ഇന്ത്യ HMIS മന്ത്ലി ഫോർമാറ്റ്. WardSynQ-ന്റെ റെക്കോർഡ് പിന്തുണയ്ക്കുന്ന ഇനങ്ങൾ ഇതിൽ നിന്ന് പൂരിപ്പിക്കുന്നു; മറ്റെല്ലാ ഇനങ്ങളും അടയാളപ്പെടുത്തിയിട്ടുണ്ട്, റിട്ടേൺ സമർപ്പിക്കുന്നതിന് മുമ്പ് ഹോസ്പിറ്റലിന്റെ സ്വന്തം രജിസ്റ്ററുകളിൽ നിന്ന് പൂരിപ്പിക്കണം.",
