    "site.admin.growth.intro": "കുട്ടികളുടെ growth charts public domain-ലുള്ള CDC 2000 growth reference ഉപയോഗിക്കുന്നു. WHO അല്ലെങ്കിൽ IAP പോലുള്ള മറ്റ് growth tables ഉപയോഗിക്കാൻ ലൈസൻസുള്ള ആശുപത്രിക്ക് അവരുടെ L, M, S മൂല്യങ്ങൾ ഇവിടെ നൽകാം, തുടർന്ന് ചാർട്ടുകൾ അവ ഉപയോഗിക്കും.",
