    "site.admin.growth.file": "CSV അല്ലെങ്കിൽ tab-separated file",
    "site.admin.growth.columns": "ആദ്യ വരി indicator, sex, x, l, m, s എന്നീ കോളം പേരുകൾ നൽകുന്നു. indicator എന്നത് wfa (weight for age), lhfa (length or height for age), wfl (weight for length, 2 വയസ്സിൽ താഴെ), wfh (weight for height, 2 വയസ്സ് മുതൽ), bmi അല്ലെങ്കിൽ hcfa (head circumference) ആണ്; sex എന്നത് 1 അല്ലെങ്കിൽ 2 ആണ്; x എന്നത് മാസങ്ങളിലുള്ള പ്രായം, അല്ലെങ്കിൽ wfl, wfh എന്നിവയ്ക്ക് cm-ലുള്ള length അല്ലെങ്കിൽ height ആണ്. ഒരു തെറ്റായ വരിയുണ്ടെങ്കിൽ പോലും ഒന്നും ലോഡ് ചെയ്യപ്പെടില്ല.",
