    "site.admin.hospital.bloodCentre.intro": "Drugs and Cosmetics Rules 1945 ആണ് ലൈസൻസുള്ള ഒരു ബ്ലഡ് സെന്ററിനായി ഇവ നിശ്ചയിക്കുന്നത്. ആശുപത്രിക്ക് ഇവ കൂടുതൽ കർശനമാക്കാൻ മാത്രമേ സാധിക്കൂ: NAT നിർബന്ധമാക്കുക, ഷെൽഫ് ലൈഫ് കുറയ്ക്കുക, സാമ്പിളുകളോ റെക്കോർഡുകളോ കൂടുതൽ കാലം സൂക്ഷിക്കുക. ഒഴിച്ചിട്ടാൽ റൂൾസ് ബാധകമാകും.",
