    "site.admin.hospital.bloodCentre.natNote": "റൂൾസ് പ്രകാരം നിർബന്ധമില്ല. 2026 മാർച്ചിനുള്ളിൽ NAT നിർബന്ധമാക്കുന്നത് സർക്കാർ നിരസിച്ചതായി റിപ്പോർട്ടുകളുണ്ട്; ഇത് ഔദ്യോഗികമായി സ്ഥിരീകരിച്ചിട്ടില്ല.",
