    "site.blood.natOptional": "ഇവിടെ NAT ഓപ്ഷണൽ ആണ്: നിയമങ്ങൾ ഇത് നിർബന്ധമാക്കുന്നില്ല, കൂടാതെ അഡ്മിനിൽ ഈ ആശുപത്രി ഇത് നിർബന്ധമാക്കിയിട്ടുമില്ല. Reactive ആയ NAT വരുന്നത് രക്തദാനം നശിപ്പിക്കുന്നതിനായി Hold ചെയ്യുന്നതിന് കാരണമാകും.",
