    "site.blood.shelfNoteLaw": "Drugs and Cosmetics Rules 1945 ഓരോ ഘടകത്തിന്റെയും കാലാവധി നിശ്ചയിച്ചിട്ടുള്ളതിനാൽ (Schedule P, Schedule F Part XII-B), ശേഖരിച്ച സമയം, ബാഗിലെ anticoagulant, additive solution എന്നിവ കണക്കാക്കിയാണ് കാലാവധി നിർണ്ണയിക്കുന്നത്. അനുവദനീയമായ പരമാവധി സമയത്തിനായി കാലാവധി ഒഴിച്ചിടുക, അല്ലെങ്കിൽ നേരത്തെയുള്ള ഒന്ന് നൽകുക. നിയമങ്ങൾ നിർദ്ദേശിച്ചതുപോലെയാണ് സ്റ്റോറേജ് രേഖപ്പെടുത്തുന്നത്.",
