    "site.gov.law.dpdpNow": "{date} മുതൽ ഈ ആശുപത്രിക്ക് DPDP Act 2023, DPDP Rules 2025 എന്നിവ ബാധകമാണ്. SPDI Rules 2011, CERT-In ചുമതലകൾ എന്നിവ ഒപ്പം നിലനിർത്തുന്നു.",
