    "site.gov.law.dayNote": "ഗസറ്റ് തീയതി 13 നവംബർ 2025 ആണ്, 14-നാണ് പ്രസിദ്ധീകരിച്ചത്; ആദ്യ ദിനമാണ് കണക്കാക്കുന്നത്. ഇത് ഒരു പ്രാക്ടീസ് ചെയ്യുന്ന അഭിഭാഷകന്റെ പരിശോധനയ്ക്കായി കാത്തിരിക്കുന്ന നിയമപരമായ ഗവേഷണമാണ്, നിയമോപദേശമല്ല.",
