    "site.gov.clocks.rule": "{date}-ന് മുൻപ് ഓരോ റിക്കവസ്റ്റും SPDI ഗ്രീവൻസ് സമയത്തിനുള്ളിൽ (ഒരു മാസം, പരമാവധി 30 ദിവസം) മറുപടി നൽകും. {date} മുതൽ ഓരോ തരത്തിലുള്ള റിക്കവസ്റ്റിനും അതിന്റേതായ DPDP സമയമുണ്ട് (പരമാവധി 90 ദിവസം). ഹോസ്പിറ്റലിന് ഇതിലും കുറഞ്ഞ സമയം നിർണ്ണയിക്കാം, ഒരിക്കലും കൂടുതൽ സമയം പാടില്ല.",
