    "site.gov.lh.title": "Legal hold: ഒന്നും മായ്ക്കാനോ നശിപ്പിക്കാനോ പാടില്ല",
    "site.gov.lh.auto": "മെഡിക്കോ-ലീഗൽ കേസ് രജിസ്റ്റർ സെറ്റ് ചെയ്തത്",
