    "site.gov.req.clockDpdp": "DPDP Rules 2025 പ്രകാരമുള്ള മറുപടി സമയം:",
    "site.gov.req.clockSpdi": "SPDI Rules 2011 പ്രകാരമുള്ള മറുപടി സമയം (DPDP പ്രാബല്യത്തിൽ വന്നതിനു ശേഷം ലഭിക്കുന്ന അഭ്യർത്ഥനകൾക്ക് അതിൻ്റെ സമയം ബാധകമാണ്):",
    "site.gov.req.contact": "മറുപടിയിൽ ബന്ധപ്പെടേണ്ട വ്യക്തിയെ സൂചിപ്പിച്ചിട്ടുണ്ട്:",
    "site.gov.req.copiesNote": "രോഗിയോ അധികാരപ്പെടുത്തിയ സഹായിയോ നിയമപരമായ അധികാരിയോ മെഡിക്കൽ റെക്കോർഡുകളുടെ പകർപ്പുകൾക്കായി നൽകുന്ന അഭ്യർത്ഥന, രോഗിയുടെ ചാർട്ടിൽ വിവരങ്ങൾ കൈമാറിയതായി (release of information) രേഖപ്പെടുത്തുന്നു, അവിടെ 72 മണിക്കൂർ ക്ലോക്ക് പ്രവർത്തിക്കുന്നു (IMC Regulations 2002 reg 1.3.2).",
    "site.gov.clocks.reasonNeeded": "72 മണിക്കൂറിൽ കൂടുതൽ സമയത്തിന് കുറഞ്ഞത് 10 അക്ഷരങ്ങളുള്ള ഒരു കാരണം ആവശ്യമാണ്; കാരണം ഇല്ലെങ്കിൽ 72 മണിക്കൂർ ലക്ഷ്യം ഉപയോഗിക്കും.",
    "site.gov.ret.unreadable": "ആശുപത്രി സൂക്ഷിക്കണമെന്ന് നിയമം അനുശാസിക്കുന്ന വിവരങ്ങൾ മനസ്സിലാക്കാൻ കഴിഞ്ഞില്ല. ഇത് വിവരങ്ങളൊന്നും സൂക്ഷിച്ചിട്ടില്ല എന്നതിന് തുല്യമല്ല.",
    "site.gov.br.pi.nature": "(a) ലംഘനത്തിൻ്റെ സ്വഭാവം, വ്യാപ്തി, സമയം",
    "site.gov.br.pi.consequences": "(b) രോഗിക്ക് ഉണ്ടാകാൻ സാധ്യതയുള്ള പ്രത്യാഘാതങ്ങൾ",
    "site.gov.br.pi.mitigation": "(c) ആഘാതം കുറയ്ക്കാൻ ആശുപത്രി ചെയ്ത കാര്യങ്ങൾ",
    "site.gov.br.pi.safety": "(d) സ്വയം സുരക്ഷിതനാകാൻ രോഗിക്ക് ചെയ്യാവുന്ന കാര്യങ്ങൾ",
    "site.gov.br.pi.contact": "(e) സംശയങ്ങൾക്ക് ബന്ധപ്പെടേണ്ട വ്യക്തി",
    "site.gov.br.bh.facts": "പുതുക്കിയ വിവരങ്ങൾ: സ്വഭാവം, വ്യാപ്തി, സമയം, സ്ഥലം, ആഘാതം",
    "site.gov.br.bh.circumstances": "സാഹചര്യങ്ങളും കാരണങ്ങളും",
    "site.gov.br.bh.mitigation": "ആപത്ത് കുറയ്ക്കുന്നതിനായി സ്വീകരിച്ച നടപടികൾ",
    "site.gov.br.bh.findings": "ലംഘനത്തിന് കാരണക്കാരനായ വ്യക്തിയെക്കുറിച്ചുള്ള കണ്ടെത്തലുകൾ",
    "site.gov.br.bh.remedial": "ഇത് ആവർത്തിക്കാതിരിക്കാനുള്ള പരിഹാര നടപടികൾ",
    "site.gov.br.boardNotInForce": "Board ചുമതലയില്ല: DPDP പ്രാബല്യത്തിൽ വരുന്നതിന് മുമ്പ് ആശുപത്രി ഇത് അറിഞ്ഞിരുന്നു",
    "site.gov.br.withdrawn": "വ്യക്തിഗത ഡാറ്റാ ചോർച്ചയല്ല (രണ്ടാമതൊരാൾ സ്ഥിരീകരിച്ചത്)",
    "site.gov.br.aware": "ആശുപത്രിയുടെ ശ്രദ്ധയിൽപ്പെട്ടു",
    "site.gov.br.certIn": "CERT-In (6 മണിക്കൂർ, ഇപ്പോൾ പ്രാബല്യത്തിലുണ്ട്)",
    "site.gov.br.boardInitial": "Board നെ ആദ്യം അറിയിച്ചു (കാലതാമസമില്ലാതെ)",
    "site.gov.br.boardDetailed": "Data Protection Board, വിശദമായ റിപ്പോർട്ട് (72 മണിക്കൂർ)",
