    "site.gov.br.principals2": "ബാധിക്കപ്പെട്ട രോഗികൾ (ആശുപത്രി ലക്ഷ്യം)",
    "site.gov.br.toldPatients": "രോഗികളോട് എന്താണ് പറഞ്ഞത്",
    "site.gov.br.boardReport": "Board-നുള്ള റിപ്പോർട്ട്",
