    "site.gov.br.notBreach": "വ്യക്തിഗത ഡാറ്റാ ചോർച്ചയല്ലെന്ന് നിർദ്ദേശിച്ചു",
    "site.gov.br.ev.certIn": "CERT-In-ൽ വിവരം അറിയിച്ചു",
    "site.gov.br.ev.boardInitial": "Board-ൽ ആദ്യം വിവരം അറിയിച്ചു",
    "site.gov.br.ev.boardDetailed": "വിശദമായ റിപ്പോർട്ട് Board-ലേക്ക് അയച്ചു",
    "site.gov.br.ev.extension": "Board കൂടുതൽ സമയം അനുവദിച്ചു",
    "site.gov.br.ev.notBreach": "നിർദ്ദേശിക്കുക: വ്യക്തിഗത ഡാറ്റാ ചോർച്ചയല്ല",
    "site.gov.br.ev.confirmNotBreach": "സ്ഥിരീകരിക്കുക: വ്യക്തിഗത ഡാറ്റാ ചോർച്ചയല്ല (രണ്ടാമതൊരാൾ)",
    "site.gov.br.extendedTo": "Board-ന്റെ പുതിയ തീയതി (extension മാത്രം)",
    "site.gov.br.text2": "വിവരങ്ങൾ: assessment, CERT-In അല്ലെങ്കിൽ Board reference, Board-ൽ ആദ്യം എന്താണ് പറഞ്ഞത്, രോഗികളോട് എങ്ങനെയാണ് പറഞ്ഞത്, ചെയ്ത നടപടി, എന്തുകൊണ്ടാണ് ഇത് ലംഘനമല്ലാത്തത്, അല്ലെങ്കിൽ സമറി അവസാനിപ്പിക്കൽ",
    "site.gov.br.piTitle": "രോഗികളോട് എന്താണ് പറഞ്ഞത് (DPDP Rules 2025 r.7(1), അഞ്ചും)",
    "site.gov.br.bhTitle": "Board-നുള്ള വിശദമായ റിപ്പോർട്ട് (DPDP Rules 2025 r.7(2)(b))",
    "site.gov.br.law2": "ഡാറ്റാ ലംഘനം ഉൾപ്പെടെയുള്ള ഒരു സൈബർ സെക്യൂരിറ്റി ഇൻസിഡന്റ് ശ്രദ്ധയിൽപ്പെട്ട് 6 മണിക്കൂറിനുള്ളിൽ CERT-In-ൽ റിപ്പോർട്ട് ചെയ്യുക (ഇപ്പോൾ പ്രാബല്യത്തിലുണ്ട്). DPDP പ്രാബല്യത്തിൽ വരുന്നത് മുതൽ Data Protection Board-ൽ കാലതാമസമില്ലാതെ വിവരമറിയിക്കുകയും ശ്രദ്ധയിൽപ്പെട്ട് 72 മണിക്കൂറിനുള്ളിൽ വിശദമായ റിപ്പോർട്ട് അയക്കുകയും വേണം, കൂടാതെ ബാധിക്കപ്പെട്ട ഓരോ രോഗിയെയും കാലതാമസമില്ലാതെ വിവരമറിയിക്കണം. 'not notifiable' എന്ന അവസ്ഥയില്ല: വ്യക്തിഗത ഡാറ്റാ ലംഘനമല്ല എന്ന് രണ്ടാമതൊരാൾ സ്ഥിരീകരിച്ചാൽ മാത്രമേ റെക്കോർഡ് പിൻവലിക്കൂ. ലംഘനം നടപ്പറ്റ വ്യക്തിഗത ഡാറ്റ ഇവിടെ എഴുതരുത്.",
    "site.gov.br.awareAt": "ആശുപത്രി ശ്രദ്ധയിൽപ്പെട്ട സമയം (പിന്നീടാണെങ്കിൽ)",
    "site.gov.br.missing": "ഇനിയും രേഖപ്പെടുത്താനുള്ളവ: {list}.",
    "site.gov.br.part": "വിവരങ്ങൾ ലഭ്യമല്ല: {part}.",
    "site.gov.nt.p.data": "ശേഖരിച്ച പേഴ്സണൽ ഡാറ്റ, ഓരോന്നായി",
    "site.gov.nt.p.purposes": "കാരണം: നിർദ്ദിഷ്ട സേവനങ്ങൾ അല്ലെങ്കിൽ ഉപയോഗങ്ങൾ",
    "site.gov.nt.p.withdraw": "സമ്മതം എങ്ങനെ പിൻവലിക്കാം, അത് നൽകിയ അത്രതന്നെ എളുപ്പത്തിൽ",
    "site.gov.nt.p.rights": "ആക്സസ്, തിരുത്തൽ, മായ്ക്കൽ അല്ലെങ്കിൽ നോമിനിയെ ആവശ്യപ്പെടുന്നത് എങ്ങനെ",
    "site.gov.nt.p.recipients": "ഡാറ്റ ആരുമായാണ് പങ്കിടുന്നത്",
    "site.gov.nt.p.agency": "ആശുപത്രിയുടെ പേരും വിലാസവും",
    "site.gov.nt.p.board": "ഡാറ്റാ പ്രൊട്ടക്ഷൻ ബോർഡിന് എങ്ങനെ പരാതി നൽകാം (DPDP ആരംഭിക്കുന്നത് മുതൽ ആവശ്യം)",
    "site.gov.nt.s5b": "നോട്ടീസ് പ്രസിദ്ധീകരിക്കുന്നതിന് മുമ്പ് താഴെ പറയുന്ന ഓരോ ഭാഗവും ആവശ്യമാണ്: ഓരോ ഡാറ്റയും, ആവശ്യങ്ങൾ, പിൻവലിക്കൽ, അവകാശങ്ങൾ, സ്വീകർത്താക്കൾ, ആശുപത്രിയുടെ പേരും വിലാസവും (DPDP Rules 2025 r.3; SPDI Rules 2011 r.5(3)), കൂടാതെ ഡാറ്റാ പ്രൊട്ടക്ഷൻ ഓഫീസർ അല്ലെങ്കിൽ ഗ്രീവൻസ് ഓഫീസർ കോൺടാക്റ്റ്. ഇത് ഇംഗ്ലീഷിലോ എട്ടാം ഷെഡ്യൂളിലെ ഒരു ഭാഷയിലോ എഴുതുക. വീണ്ടും പ്രസിദ്ധീകരിക്കുന്നത് ഒരു പുതിയ വേർഷൻ ഉണ്ടാക്കുന്നു; രോഗികൾ ഒരു വേർഷൻ അംഗീകരിക്കുന്നു. DPDP ആരംഭിക്കുന്നതിന് മുമ്പ് നോട്ടീസ് നൽകിയ രോഗികൾക്ക് പുതിയൊരെണ്ണം ആവശ്യമാണ് (s.5(2)).",
    "site.gov.nt.textOptional": "നോട്ടീസിൽ പറയുന്ന മറ്റെന്തെങ്കിലും (ഓപ്ഷണൽ)",
    "site.gov.nt.dpo2": "ഡാറ്റാ പ്രൊട്ടക്ഷൻ ഓഫീസർ അല്ലെങ്കിൽ ഗ്രീവൻസ് ഓഫീസർ കോൺടാക്റ്റ് (പ്രസിദ്ധീകരിച്ചത്)",
    "site.gov.nt.oldVersion": "വ്യക്തമാക്കിയ ഭാഗങ്ങൾ നിർബന്ധമാക്കുന്നതിന് മുമ്പാണ് ഈ വേർഷൻ പ്രസിദ്ധീകരിച്ചത്. ഓരോ ഭാഗവും ചേർത്ത് ഇത് വീണ്ടും പ്രസിദ്ധീകരിക്കുക.",
    "site.gov.lh.r.mlc": "Medico-legal കേസ്",
