    "site.gov.lh.r.police": "പോലീസ് അഭ്യർത്ഥന",
    "site.gov.ret.title": "രേഖകൾ സൂക്ഷിക്കുന്ന കാലാവധി",
    "site.gov.ret.intro2": "ഒന്നും സ്വയം ഡിലീറ്റ് ചെയ്യപ്പെടില്ല. ഓരോ തരവും അത് സൂക്ഷിക്കുന്നതിന്റെ കാരണം വ്യക്തമാക്കുന്നു: ബന്ധപ്പെട്ട വകുപ്പോടു കൂടിയ നിയമം, അല്ലെങ്കിൽ ആശുപത്രിയുടെ retention policy (ഇത് നിയമപരമായ ആവശ്യമല്ല). നിയമപരമായ ഹോൾഡ് ഉണ്ടെങ്കിൽ വിഷയം തീർപ്പാക്കുന്നതുവരെ എല്ലാം സൂക്ഷിക്കും. നിയമം നിർദ്ദേശിച്ച കാലാവധിക്കുള്ളിൽ രേഖകൾ ഡിലീറ്റ് ചെയ്യുന്നത് നിരസിക്കപ്പെടും; പോളിസി മാത്രം നിർദ്ദേശിച്ച കാലാവധിക്കുള്ളിലാണെങ്കിൽ DPO അല്ലെങ്കിൽ മെഡിക്കൽ റെക്കോർഡ്സ് ഓഫീസറുടെ സ്ഥിരീകരണം ആവശ്യമാണ്.",
    "site.gov.ret.find": "Retention കാണിക്കുക",
    "site.gov.ret.loading": "ഏതൊക്കെ സൂക്ഷിക്കണമെന്ന് പരിശോധിച്ച് വരുന്നു...",
