    "site.gov.ret.decErase": "DPO ഇത് മായ്ച്ചു കളയാൻ തീരുമാനിച്ചു:",
    "site.gov.ret.decDestroyed": "നശിപ്പിച്ചതിന്റെ റെക്കോർഡ് {ref}",
    "site.gov.ret.decTitle": "ആശുപത്രിയുടെ റിട്ടൻഷൻ നയം അനുസരിച്ച് മാത്രം സൂക്ഷിച്ചിരിക്കുന്നു: DPO തീരുമാനമെടുക്കുന്നു",
    "site.gov.ret.decIntro": "ഈ റെക്കോർഡുകൾ ഒരു നിയമപ്രകാരവും സൂക്ഷിക്കുന്നില്ല. ഓരോന്നിനും, അത് നിലനിർത്തി ആവശ്യകത അല്ലെങ്കിൽ ഉദ്ദേശ്യം എഴുതുക, അല്ലെങ്കിൽ മായ്ക്കുക. WardSynQ ഒരു ക്ലിനിക്കൽ റെക്കോർഡ് സ്വയം മായ്ച്ചുകളയില്ല: മെഡിക്കൽ റെക്കോർഡ്സ് ഓഫീസർ അത് നശിപ്പിക്കുകയോ ഡീ-ഐഡന്റിഫൈ ചെയ്യുകയോ ചെയ്യുന്നു, കൂടാതെ ഡിസ്ട്രക്ഷൻ റെക്കോർഡ് റഫറൻസോടെ അഭ്യർത്ഥന പൂർത്തിയാക്കുന്നു.",
    "site.gov.ret.decision": "തീരുമാനം",
