    "site.gov.ret.classesLoading": "റിറ്റൻഷൻ ക്ലാസുകൾ ലോഡ് ചെയ്യുന്നു...",
    "site.gov.ret.classesFailed": "റിറ്റൻഷൻ ക്ലാസുകൾ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. ക്ലാസുകൾ ഒന്നും തന്നെ ഇല്ല എന്നതിൻ്റെ അർത്ഥമല്ല ഇത്.",
    "site.gov.ret.dpdpNow": "DPDP ബാധകമാണ്: നിയമം നിശ്ചയിച്ചിട്ടുള്ള കാലയളവ് ഡാറ്റ മായിച്ചുകളയുന്നത് തടയുന്നു; ആശുപത്രിയുടെ പോളിസി മാത്രം നിശ്ചയിച്ചിട്ടുള്ള കാലയളവ് രേഖാമൂലമുള്ള തീരുമാനത്തിനായി DPO-യിലേക്ക് അയക്കുന്നു.",
    "site.gov.ret.dpdpLater": "DPDP പ്രാബല്യത്തിൽ വരുന്നത് വരെ ഡാറ്റ മായിച്ചുകളയുന്നത് താഴെ പറയുന്ന എല്ലാ ക്ലാസുകളും നിലനിർത്തുന്നു. അതിനുശേഷം, നിയമം നിശ്ചയിച്ചിട്ടുള്ള കാലയളവ് ഡാറ്റ മായിക്കുന്നതിനെ തടയുന്നു; ആശുപത്രിയുടെ പോളിസി മാത്രം നിശ്ചയിച്ചിട്ടുള്ള കാലയളവ് രേഖാമൂലമുള്ള തീരുമാനത്തിനായി DPO-യിലേക്ക് അയക്കുന്നു.",
