    "site.admin.tariff.nonHealth": "ഹെൽത്ത് കെയർ അല്ല (അറ്റൻഡന്റ് ഫുഡ് അല്ലെങ്കിൽ ബെഡ്, കോസ്മെറ്റിക് പ്രൊസീജർ, റീട്ടെയിൽ ഐറ്റം): അഡ്മിറ്റ് ചെയ്ത രോഗിയാണെങ്കിലും സ്വന്തം നിരക്കിൽ ടാക്സ് ഈടാക്കുന്നു",
    "site.admin.tariff.icuQuestion": "ഈ റൂം കാറ്റഗറി ഒരു Intensive Care Unit, Critical Care Unit, Intensive Cardiac Care Unit അല്ലെങ്കിൽ Neonatal Intensive Care Unit ആണോ? ഏത് തുകയ്ക്കും ഇവയ്ക്ക് മാത്രമാണ് ഇളവുള്ളത്. High dependency, step-down, isolation, labour room എന്നിവ ഈ ലിസ്റ്റിൽ ഇല്ല, അവ പ്രതിദിനം Rs 5,000 നിയമം പിന്തുടരുന്നു.",
    "site.admin.tariff.errHours": "ഒരു ബെഡ് നിരക്കിൽ ഉൾപ്പെടുന്ന മണിക്കൂറുകൾ 1 മുതൽ 24 വരെയുള്ള പൂർണ്ണ സംഖ്യയായിരിക്കണം.",
    "site.admin.tariff.icuOtherPrompt": "{name} ഒരു specialty ICU (PICU, MICU, SICU) ആണോ അതോ high dependency അല്ലെങ്കിൽ step-down unit ആണോ? SPECIALTY അല്ലെങ്കിൽ HDU എന്ന് ടൈപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ സാധാരണ മുറിയാണെങ്കിൽ ഒഴിഞ്ഞിടുക.",
    "site.admin.tariff.errIcuOther": "SPECIALTY, HDU എന്ന് ടൈപ്പ് ചെയ്യുക, അല്ലെങ്കിൽ ഒഴിഞ്ഞിടുക.",
