    "site.admin.gst.recipientPerContract": "GST സ്വീകർത്താവിനെ (Section 2(93) CGST Act) Integrations, Payers എന്നതിന് കീഴിലുള്ള ഓരോ പേയർ കരാറിലും നിർണ്ണയിക്കുന്നത് ആരാണ് പണം നൽകാൻ ബാധ്യസ്ഥരെന്നതിൻ്റെ അടിസ്ഥാനത്തിലാണ്, ആരാണ് പണം ട്രാൻസ്ഫർ ചെയ്യുന്നത് എന്നതിൻ്റെ അടിസ്ഥാനത്തിലല്ല. ഇൻഷുറർമാരും TPA-കളും ഡിഫോൾട്ടായി രോഗിയുടെ പേരിൽ വരും; ഗവൺമെൻ്റ് സ്കീമുകളും കോർപ്പറേറ്റ് കരാറുകളും നിങ്ങൾ തിരഞ്ഞെടുക്കുന്നത് വരെ നിർണ്ണയിക്കപ്പെടാതെ തുടരുകയും രോഗിക്ക് മുന്നറിയിപ്പോടെ ബിൽ ചെയ്യപ്പെടുകയും ചെയ്യും.",
    "site.admin.gst.recipientLegacy": "നിങ്ങളുടെ മുൻപത്തെ ആശുപത്രി തലത്തിലുള്ള ക്രമീകരണം ഇൻഷുറർ, TPA അല്ലെങ്കിൽ സ്കീമിനെ GST സ്വീകർത്താവമാക്കിയിരുന്നു. ഓരോ കരാറിലും പുതിയത് രേഖപ്പെടുത്തുന്നത് വരെ, താഴെ പറയുന്ന ചാർട്ടേഡ് അക്കൗണ്ടൻ്റിൻ്റെ അഭിപ്രായത്തിൻ്റെ അടിസ്ഥാനത്തിൽ, സ്വന്തമായി നിർണ്ണയം ഇല്ലാത്ത പേയർ കരാറുകൾക്ക് മാത്രമായി ഇത് ഉപയോഗിക്കുന്നു.",
