    "site.admin.import.stopped": "{parts}-ൽ {part} ഭാഗം നിർത്തുന്നതിന് മുമ്പ് {n} വരികൾ ഇറക്കുമതി ചെയ്തു. ഡ്രൈ റൺ വീണ്ടും പ്രവർത്തിപ്പിക്കുക: ഇറക്കുമതി ചെയ്തവ ഇതിനകം ഇവിടെയുള്ളതായി കാണിക്കും, കൂടാതെ ഇറക്കുമതി ചെയ്യുന്നത് വിട്ടുപോയവ മാത്രമാണ് ചേർക്കുന്നത്.",
