    "site.admin.fml.yesNoNote": "നിയന്ത്രിതമാണ്, അപ്രൂവലും കൺട്രോൾഡ് റീഡ് അതെ അല്ലെങ്കിൽ അല്ല എന്നും ആവശ്യമാണ്. ലിസ്റ്റുകൾ ; ഉപയോഗിച്ച് വേർതിരിച്ചിരിക്കുന്നു.",
