    "site.admin.ccs.critical.title": "Critical പരിധികൾ",
    "site.admin.ccs.critical.intro": "ലാബ് ഫലം critical result loop ആരംഭിക്കുന്ന അതിരുകളായ കുറഞ്ഞതും കൂടിയതുമായ മൂല്യങ്ങൾ. ലാബിന്റെ സ്വന്തം critical flag എപ്പോഴും പരിഗണിക്കും. ഇവിടെ ലിസ്റ്റ് ചെയ്യാത്ത ഒരു അanalyറ്റിന് താഴെ കാണിച്ചിരിക്കുന്ന built-in adult default ബാധകമാകും.",
    "site.admin.ccs.critical.empty": "ഈ ആശുപത്രിക്കായി Critical limits ഒന്നും സേവ് ചെയ്തിട്ടില്ല. പരിധികൾ സേവ് ചെയ്യുന്നത് വരെ താഴെയുള്ള built-in adult defaults ബാധകമാകും.",
    "site.admin.ccs.delta.title": "Delta check പരിധികൾ",
    "site.admin.ccs.delta.intro": "സാമ്പിൾ ഐഡന്റിറ്റി ചെക്കിനായി ഫലം ഫ്ലാഗ് ചെയ്യുന്നതിന് മുമ്പ്, രോഗിയുടെ മുൻ ഫലത്തിൽ നിന്നുള്ള ഏറ്റവും വലിയ മാറ്റം (ഫലത്തിന്റെ സ്വന്തം unit-ലോ ശതമാനത്തിലോ). ഒരു ഫലവും തടഞ്ഞുവെക്കില്ല. വ്യത്യസ്ത unit-കളിലുള്ള ഫലങ്ങൾ താരതമ്യം ചെയ്യില്ല. മറ്റൊരു സമയം നൽകിയിട്ടില്ലെങ്കിൽ മുൻ ഫലം 72 മണിക്കൂർ വരെ പരിഗണിക്കും.",
    "site.admin.ccs.delta.empty": "Delta limits ഒന്നും സേവ് ചെയ്തിട്ടില്ല. ഫലങ്ങൾ delta check ചെയ്യപ്പെടുന്നില്ല, ഓരോ ഫലത്തിലും അത് വ്യക്തമാക്കും.",
    "site.admin.ccs.auto.intro": "ഫലം സംഖ്യാപരവും, reference range-ന് ഉള്ളിലും, ലാബ് critical ആയി ഫ്ലാഗ് ചെയ്യാത്തതും, delta breach ഇല്ലാത്തതുമാകുമ്പോൾ നേരിട്ട് റിലീസ് ചെയ്യാവുന്ന പരിശോധനകൾ. മറ്റെന്തും നേരിട്ട് പരിശോധിച്ച് ഉറപ്പുവരുത്തും.",
    "site.admin.ccs.auto.empty": "Autoverification കോൺഫിഗർ ചെയ്തിട്ടില്ല. ഓരോ ഫലവും പരിശോധിച്ച് ഉറപ്പുവരുത്തുന്നു.",
    "site.admin.ccs.mar.title": "മരുന്ന് നൽകുന്ന സമയങ്ങൾ",
    "site.admin.ccs.mar.intro": "ഒരു പ്രത്യേക frequency നൽകേണ്ട സമയം, 24 മണിക്കൂർ ക്ലോക്കിൽ, ദിവസ ക്രമത്തിൽ. TDS, QID സമയങ്ങൾ 1-0-1, 1-0-0-1 രേഖപ്പെടുത്തലുകളും നിശ്ചയിക്കുന്നു. ഇവിടെ ലിസ്റ്റ് ചെയ്യാത്ത ഒരു frequency-ക്ക് താഴെ കാണിച്ചിരിക്കുന്ന built-in round ബാധകമാകും.",
    "site.admin.ccs.mar.empty": "Round times ഒന്നും സേവ് ചെയ്തിട്ടില്ല. സമയങ്ങൾ സേവ് ചെയ്യുന്നത് വരെ താഴെയുള്ള built-in round ബാധകമാകും.",
    "site.admin.ccs.notes.title": "Note ടെംപ്ലേറ്റുകൾ",
    "site.admin.ccs.notes.intro": "ഈ ആശുപത്രിയുടെ ക്ലിനിക്കൽ നോട്ടുകളുടെ ഹെഡ്ഡിംഗുകൾ. ഒരു സെക്ഷൻ ഒരു ചോദ്യം ചോദിക്കുന്നു, അതിൽ ഡിഫോൾട്ട് ടെക്സ്റ്റ് ഉണ്ടാകില്ല. ഒരു വരിയിൽ ഒരു സെക്ഷൻ: key | title | question | required. ഒരു ബിൽറ്റ്-ഇൻ നോട്ടിന്റെ id ഉള്ള ടെംപ്ലേറ്റ് അതിന് പകരം വരുന്നതാണ്.",
    "site.admin.ccs.notes.empty": "Note ടെംപ്ലേറ്റുകളൊന്നും സേവ് ചെയ്തിട്ടില്ല. ടെംപ്ലേറ്റുകൾ സേവ് ചെയ്യുന്നത് വരെ ബിൽറ്റ്-ഇൻ നോട്ടുകൾ കാണിക്കും.",
