    "site.admin.sourceOrders.intro": "ഒരു ലബോറട്ടറി സിസ്റ്റമോ മറ്റൊരു ആശുപത്രിയോ അയച്ച ഓർഡറുകൾ ഡ്രാഫ്റ്റുകളായി ഇവിടെ റെക്കോർഡ് ചെയ്യുന്നു, കാരണം ബന്ധിപ്പിച്ച സിസ്റ്റത്തിന് WardSynQ-ൽ ക്ലിനിക്കൽ സ്റ്റാറ്റസ് സജ്ജീകരിക്കാൻ കഴിഞ്ഞേക്കില്ല. അവിടെ റിസൾട്ട് ഫയൽ ചെയ്യുമ്പോൾ, ഇവിടുത്തെ ഒന്നും തന്നെ ഓർഡർ പൂർത്തിയായതായി മാർക്ക് ചെയ്യുന്നില്ല, അത് എന്നെന്നേക്കുമായി ഓപ്പൺ വർക്കായി കണക്കാക്കപ്പെടുന്നു. ചെക്ക് ചെയ്യുന്നത് ഓർഡറുകൾ റീഡ് ചെയ്യുന്നു, ഒന്നും റൈറ്റ് ചെയ്യുന്നില്ല. ക്ലോസ് ചെയ്യുന്നത് അയച്ച സിസ്റ്റം തന്നെ പൂർത്തിയായതായി പ്രഖ്യാപിച്ച ഓർഡറുകളെ മാത്രമാണ്; അത് ആക്റ്റീവ് എന്ന് പറയുന്നവയോ, ഒന്നും പറയാത്തവയോ, ഈ ആശുപത്രിയുടെ സ്വന്തം ഓർഡറുകളോ മാറ്റമില്ലാതെ നിലനിർത്തുന്നു.",
    "site.admin.sourceOrders.failed": "എന്തോ റീഡ് ചെയ്യാനോ റൈറ്റ് ചെയ്യാനോ കഴിയാത്തതിനാൽ ജോലി തടസ്സപ്പെട്ടു. ഇനി ഒന്നും ചെയ്യാനില്ല എന്നതിന്റെ അർത്ഥമല്ല ഇത്; താഴെ റിപ്പോർട്ട് ചെയ്തിരിക്കുന്നത് തടസ്സപ്പെടുന്നതിന് മുമ്പ് പൂർത്തിയാക്കിയത് മാത്രമാണ്.",
